const envContent = fs.readFileSync(path.join(__dirname, '.env.test'), 'utf8');
const dbUrlLine = envContent.split('\n').find(line => line.startsWith('DATABASE_URL='));

if (!dbUrlLine) {
  console.error('DATABASE_URL not found in .env.test');
  process.exit(1);
}

// Extract the DATABASE_URL value
const dbUrl = dbUrlLine.replace('DATABASE_URL=', '');

// Create base32 encoder (simple implementation)
function base32Encode(str) {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  const bytes = Buffer.from(str, 'utf8');
  let result = '';
  let bits = 0;
  let buffer = 0;

  for (let i = 0; i < bytes.length; i++) {
    buffer = (buffer << 8) | bytes[i];
    bits += 8;

    while (bits >= 5) {
      bits -= 5;
      result += alphabet[(buffer >>> bits) & 31];
    }
  }

  if (bits > 0) {
    result += alphabet[(buffer << (5 - bits)) & 31];
  }

  // Remove padding (=)
  return result.replace(/=/g, '');
}

